from collections import namedtuple

def solve(n: int) -> str:
    """
    Given a positive integer n, determine who will win if both players play optimally.

    :param n: The starting integer.
    :return: 'First' if Vanya wins, 'Second' if Vova wins.
    """
    Turn = namedtuple('Turn', 'player value')
    turns = []
    current_player = 1
    current_value = n

    while current_value > 0:
        if current_value % 3 == 0:
            return 'First' if current_player == 1 else 'Second'

        if current_value % 10 == 0:
            return 'Second' if current_player == 1 else 'First'

        current_player = 2 if current_player == 1 else 1
        if current_player == 1:
            turns.append(Turn(current_player, current_value - 1))
        else:
            turns.append(Turn(current_player, current_value + 1))
        current_value = current_value - 1 if current_player == 1 else current_value + 1

    for i in range(len(turns)):
        if turns[i].value % 3 == 0:
            return 'First' if turns[i].player == 1 else 'Second'

        if turns[i].value % 10 == 0:
            return 'Second' if turns[i].player == 1 else 'First'

    return 'First' if current_player == 1 else 'Second'

