 def solve(n, a):
    # Initialize a dictionary to store the sums of pairs of elements
    sums = {}

    # Iterate over all possible pairs of elements
    for i in range(n):
        for j in range(i + 1, n):
            # Add the sum of the current pair to the dictionary
            sums[(a[i], a[j])] = a[i] + a[j]

    # Iterate over all possible pairs of elements
    for i in range(n):
        for j in range(i + 1, n):
            # Check if the sum of the current pair is in the dictionary
            if (a[i], a[j]) in sums:
                # If it is, remove it from the dictionary
                sums.pop((a[i], a[j]))

    # Return True if the dictionary is empty, False otherwise
    return not sums

