def is_prime(digits):
    # Check if the number of digits is 2
    if len(digits) == 2:
        return False

    # Check if the number is divisible by 2, 3, 5, or 7
    for i in range(2, len(digits)):
        if digits[i] == 0:
            return False

    # Check if the number is divisible by 11
    if sum(digits) % 11 == 0:
        return False

    # If none of the above conditions are met, the number is prime
    return True

