def divide_and_conquer(a):
    if sum(a) % 2 == 0:
        return 0
    if len(a) == 1:
        return 1
    mid = len(a) // 2
    left = divide_and_conquer(a[:mid])
    right = divide_and_conquer(a[mid:])
    if left + right == 0:
        return 0
    elif left == 0:
        return right + 1
    else:
        return left + 1

