def solve(n, m):
    # Initialize a 2D array to store the distances from each cell to the nearest isolated cell
    distances = [[-1] * m for _ in range(n)]

    # Initialize a queue to store the cells to be processed
    queue = [(0, 0)]

    # Loop until the queue is empty
    while queue:
