def is_isolated(cell, n, m):
    # Check if the cell is on the border of the board
    if cell[0] == 0 or cell[0] == n - 1 or cell[1] == 0 or cell[1] == m - 1:
        return False

    # Check if the cell has at least one neighbor that is on the border of the board
    for i in range(-1, 2):
        for j in range(-1, 2):
            if (cell[0] + i, cell[1] + j) in [(0, 0), (n - 1, 0), (n - 1, m - 1), (0, m - 1)]:
