def solve(n, cnts):
   import math

   def gcd(a, b):
       while b != 0:
           a, b = b, a % b
       return a

   def lcm(a, b):
       return a * b // gcd(a, b)

   def get_factors(n):
       factors = []
       for i in range(1, int(math.sqrt(n)) + 1):
           if n % i == 0:
               factors.append(i)
               if n // i != i:
                   factors.append(n // i)
       return factors

   def get_colors(cnts):
       colors = []
       for cnt in cnts:
           if cnt > 0:
               colors.append(cnt)
       return colors

   def get_gcd_colors(colors):
       gcd_colors = [colors[0]]
       for color in colors[1:]:
           gcd_colors.append(gcd(color, gcd_colors[-1]))
       return gcd_colors

   def get_lcm_colors(colors):
       lcm_colors = [colors[0]]
       for color in colors[1:]:
           lcm_colors.append(lcm(color, lcm_colors[-1]))
       return lcm_colors

   def get_solution(colors):
       if len(colors) == 1:
           return colors[0]
       elif len(colors) == 2:
           return gcd(colors[0], colors[1])
       else:
           factors = get_factors(len(colors))
           gcd_colors = get_gcd_colors(colors)
           lcm_colors = get_lcm_colors(colors)
           for factor in factors:
               if factor > len(colors):
                   break
               if gcd_colors[factor - 1] == 1:
                   return lcm_colors[factor - 1]
           return -1

   colors = get_colors(cnts)
   solution = get_solution(colors)
   return solution

