def solve(N: int, M: int) -> int:
    grid = [[i * M + j + 1 for j in range(M)] for i in range(N)]
    dominoes: List[List[int]] = []
    for i in range(N - 1):
        for j in range(M - 1):
            if grid[i][j] + 1 == grid[i][j + 1]:
                dominoes.append([grid[i][j], grid[i][j + 1]])
    for i in range(N - 1, -1, -1):
        for j in range(M - 1):
            if grid[i][j] - 1 == grid[i - 1][j]:
                dominoes.append([grid[i][j], grid[i - 1][j]])
