def is_valid(p1, p2):
    # Check if p2 is obtained from p1 by swapping two elements
    for i in range(n):
        for j in range(i+1, n):
            if p1[i] == p2[j] and p1[j] == p2[i]:
                # Check if the fixedness of p2 is strictly lower than p1
                if get_fixedness(p2) < get_fixedness(p1):
                    return True
    return False

def get_fixedness(p):
    return sum(p[i] == i for i in range(n))

